sp_widget.client_script:
api.controller = function ($scope, $http, $timeout) {
    var c = this;

    c.view = 'home';
    c.currentFolder = '';
    c.currentFolderName = '';
    c.searchText = '';

    c.showFolderModal = false;
    c.showShareModal = false;
    c.previewFile = null;

    c.newFolderName = '';
    c.newFolderDescription = '';

    c.selectedUser = '';
    c.sharePermission = 'Viewer';
    c.shareTarget = null;
    c.shareType = 'file';

    c.userSearchText = '';
    c.userSearchLoading = false;
    c.userSearchError = '';
    c.userSearchTimer = null;

    c.message = '';
    c.error = '';
    c.uploading = false;

    // Navigation
    c.goHome = function () {
        c.view = 'home';
        c.currentFolder = '';
        c.currentFolderName = '';
        c.searchText = '';
        c.previewFile = null;
        c.error = '';
        c.message = '';
    };

    c.setView = function (view) {
        c.view = view;
        c.currentFolder = '';
        c.currentFolderName = '';
        c.searchText = '';
        c.previewFile = null;
        c.error = '';
        c.message = '';
    };

    c.openFolder = function (folder) {
        c.currentFolder = folder.sys_id;
        c.currentFolderName = folder.folder_name;
        c.view = 'files';
        c.searchText = '';
    };

    c.backToFolders = function () {
        c.currentFolder = '';
        c.currentFolderName = '';
        c.view = 'folders';
        c.searchText = '';
    };

    // Search files
    c.searchFiles = function (file) {
        if (!c.searchText)
            return true;

        return (file.filename || '')
            .toLowerCase()
            .indexOf(c.searchText.toLowerCase()) !== -1;
    };

    c.searchFolders = function (folder) {
        if (!c.searchText)
            return true;

        return (folder.folder_name || '')
            .toLowerCase()
            .indexOf(c.searchText.toLowerCase()) !== -1;
    };

    c.filesInCurrentFolder = function () {
        return (c.data.files || []).filter(function (file) {
            return (file.folder || '') === (c.currentFolder || '');
        });
    };

    c.foldersInCurrentFolder = function () {
        return (c.data.folders || []).filter(function (folder) {
            return (folder.parent_folder || '') ===
                (c.currentFolder || '');
        });
    };

    // Server actions
    c.runAction = function (action, values) {
        values = values || {};
        values.action = action;

        c.error = '';
        c.message = '';

        return c.server.get(values).then(function (response) {
            c.data = response.data;

            if (response.data.error)
                c.error = response.data.error;

            if (response.data.success)
                c.message = response.data.success;

            return response.data;
        }, function () {
            c.error = 'Server request failed. Please try again.';
            return {
                error: c.error
            };
        });
    };

    c.refresh = function () {
        return c.server.update().then(function (response) {
            c.data = response.data;
            return response.data;
        });
    };

    // Create folder
    c.createFolder = function () {
        var folderName = (c.newFolderName || '').trim();

        if (!folderName) {
            c.error = 'Please enter a folder name.';
            return;
        }

        c.runAction('create_folder', {
            folder_name: folderName,
            description: c.newFolderDescription || '',
            parent_folder: c.currentFolder || ''
        }).then(function (result) {
            if (result.error)
                return;

            c.showFolderModal = false;
            c.newFolderName = '';
            c.newFolderDescription = '';
            c.refresh();
        });
    };

    // Open share modal
    c.openShare = function (item, type) {
        c.shareTarget = item;
        c.shareType = type;
        c.selectedUser = '';
        c.sharePermission = 'Viewer';
        c.userSearchText = '';
        c.userSearchError = '';
        c.data.users = [];
        c.showShareModal = true;

        c.searchUsers();
    };

    // Search users with a debounce
    c.searchUsers = function () {
        if (c.userSearchTimer)
            $timeout.cancel(c.userSearchTimer);

        var term = (c.userSearchText || '').trim();

        c.selectedUser = '';
        c.userSearchError = '';
        c.data.users = [];

        if (term.length < 2) {
            c.userSearchLoading = false;
            return;
        }

        c.userSearchTimer = $timeout(function () {
            c.userSearchLoading = true;

            c.server.get({
                action: 'search_users',
                search_term: term
            }).then(function (response) {

                // Ignore results if the search term has changed.
                if (term !== (c.userSearchText || '').trim())
                    return;

                c.data.users = response.data.users || [];
                c.userSearchLoading = false;

            }, function () {
                c.userSearchLoading = false;
                c.userSearchError = 'Unable to search users.';
            });

        }, 350);
    };

    // Share
    c.shareItem = function () {
        if (!c.shareTarget || !c.selectedUser) {
            c.error = 'Please select a user.';
            return;
        }

        c.runAction('share', {
            sys_id: c.shareTarget.sys_id,
            type: c.shareType,
            user_id: c.selectedUser,
            permission: c.sharePermission
        }).then(function (result) {
            if (result.error)
                return;

            c.showShareModal = false;
            c.shareTarget = null;
            c.refresh();
        });
    };

    // Upload multiple files
    c.uploadFiles = function (element) {
        var selectedFiles = Array.prototype.slice.call(
            element.files || []
        );

        if (!selectedFiles.length)
            return;

        if (!c.currentFolder) {
            c.error = 'Please open a folder before uploading files.';
            element.value = '';
            return;
        }

        c.uploading = true;
        c.error = '';

        var index = 0;
        var failedFiles = [];

        function uploadNext() {
            if (index >= selectedFiles.length) {
                c.uploading = false;
                element.value = '';

                c.refresh().then(function () {
                    if (failedFiles.length) {
                        c.error = 'Upload failed: ' +
                            failedFiles.join(', ');
                    } else {
                        c.message = 'All files uploaded successfully.';
                    }
                });

                return;
            }

            var file = selectedFiles[index++];
            var extension = '';

            if (file.name.indexOf('.') !== -1)
                extension = file.name.split('.').pop().toLowerCase();

            c.runAction('create_file', {
                filename: file.name,
                extension: extension,
                content_type: file.type || 'application/octet-stream',
                file_size: file.size,
                folder: c.currentFolder
            }).then(function (result) {
                if (result.error || !result.file_sys_id) {
                    failedFiles.push(file.name);
                    uploadNext();
                    return;
                }

                var uploadUrl =
                    '/api/now/attachment/file' +
                    '?table_name=x_1830514_fm_file' +
                    '&table_sys_id=' +
                    encodeURIComponent(result.file_sys_id) +
                    '&file_name=' +
                    encodeURIComponent(file.name);

                $http.post(uploadUrl, file, {
                    transformRequest: angular.identity,
                    headers: {
                        'Content-Type': undefined,
                        'Accept': 'application/json'
                    }
                }).then(function () {
                    uploadNext();
                }, function () {
                    failedFiles.push(file.name);
                    uploadNext();
                });
            });
        }

        uploadNext();
    };

    // Download
    c.downloadFile = function (file) {
        if (!file || !file.attachment_id) {
            c.error = 'Attachment not found.';
            return;
        }

        window.open(
            '/sys_attachment.do?sys_id=' +
            encodeURIComponent(file.attachment_id),
            '_blank'
        );
    };

    // Image preview
    c.isImage = function (file) {
        if (!file)
            return false;

        var ext = (file.file_extension || '').toLowerCase();
        var type = (file.content_type || '').toLowerCase();

        return type.indexOf('image/') === 0 ||
            ['png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp']
                .indexOf(ext) !== -1;
    };

    c.preview = function (file) {
        if (!file || !file.attachment_id) {
            c.error = 'Image attachment not found.';
            return;
        }

        if (!c.isImage(file)) {
            c.error = 'Preview is available for image files only.';
            return;
        }

        c.previewFile = file;
    };

    c.closePreview = function () {
        c.previewFile = null;
    };

    // Edit description
    c.editFile = function (file) {
        var description = window.prompt(
            'Enter file description:',
            file.description || ''
        );

        if (description === null)
            return;

        c.runAction('update_file', {
            sys_id: file.sys_id,
            description: description
        }).then(function (result) {
            if (!result.error)
                c.refresh();
        });
    };

    // Delete file
    c.deleteFile = function (file) {
        if (!window.confirm('Move this file to Recycle Bin?'))
            return;

        c.runAction('delete_file', {
            sys_id: file.sys_id
        }).then(function (result) {
            if (!result.error)
                c.refresh();
        });
    };

    // Delete folder
    c.deleteFolder = function (folder) {
        if (!window.confirm('Move this folder to Recycle Bin?'))
            return;

        c.runAction('delete_folder', {
            sys_id: folder.sys_id
        }).then(function (result) {
            if (!result.error)
                c.refresh();
        });
    };

    // Restore file
    c.restoreFile = function (file) {
        c.runAction('restore_file', {
            sys_id: file.sys_id
        }).then(function (result) {
            if (!result.error)
                c.refresh();
        });
    };

    // Restore folder
    c.restoreFolder = function (folder) {
        c.runAction('restore_folder', {
            sys_id: folder.sys_id
        }).then(function (result) {
            if (!result.error)
                c.refresh();
        });
    };

    // Format file sizes
    c.formatBytes = function (bytes) {
        bytes = parseInt(bytes, 10) || 0;

        if (bytes === 0)
            return '0 B';

        if (bytes < 1024)
            return bytes + ' B';

        if (bytes < 1048576)
            return (bytes / 1024).toFixed(1) + ' KB';

        if (bytes < 1073741824)
            return (bytes / 1048576).toFixed(1) + ' MB';

        return (bytes / 1073741824).toFixed(2) + ' GB';
    };
};

sp_widget.css:
/* =========================================
   FILE MANAGER - MAIN LAYOUT
========================================= */

.fm-app {
    display: flex;
    width: 100%;
    min-height: 750px;
    background: #f5f7fb;
    color: #263445;
    font-family: Arial, sans-serif;
    overflow: hidden;
}

.fm-app * {
    box-sizing: border-box;
}

.fm-main {
    flex: 1;
    min-width: 0;
    padding: 25px 32px;
    background: #f5f7fb;
}

/* =========================================
   SIDEBAR
========================================= */

.fm-sidebar {
    width: 235px;
    min-width: 235px;
    background: #ffffff;
    border-right: 1px solid #e7ebf0;
    display: flex;
    flex-direction: column;
    min-height: 750px;
}

.fm-logo {
    height: 75px;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 0 23px;
    border-bottom: 1px solid #edf0f4;
    font-size: 19px;
    font-weight: 700;
    color: #263445;
    cursor: pointer;
}

.fm-logo-icon {
    width: 37px;
    height: 37px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #e9f1ff;
    color: #3478df;
    font-size: 19px;
}

.fm-menu {
    padding: 22px 12px;
    flex: 1;
}

.fm-menu-label {
    color: #9aa5b3;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 1px;
    padding: 0 12px;
    margin-bottom: 12px;
}

.fm-menu-spaced {
    margin-top: 28px;
}

.fm-menu a {
    display: flex;
    align-items: center;
    gap: 13px;
    height: 43px;
    padding: 0 13px;
    margin-bottom: 5px;
    border-radius: 7px;
    color: #657386;
    font-size: 13px;
    text-decoration: none;
    cursor: pointer;
    transition: all 0.2s ease;
}

.fm-menu a i {
    width: 17px;
    font-size: 15px;
    text-align: center;
}

.fm-menu a:hover {
    background: #f0f5ff;
    color: #3478df;
}

.fm-menu a.active {
    background: #eaf1ff;
    color: #3478df;
    font-weight: 600;
}

.fm-sidebar-footer {
    padding: 18px 22px;
    border-top: 1px solid #edf0f4;
    color: #8491a2;
    font-size: 12px;
}

.fm-sidebar-footer i {
    margin-right: 8px;
    color: #3478df;
}

/* =========================================
   HEADER
========================================= */

.fm-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
    min-height: 65px;
    margin-bottom: 25px;
}

.fm-header-title {
    min-width: 160px;
}

.fm-header-title h2 {
    margin: 0 0 6px;
    font-size: 23px;
    font-weight: 700;
    color: #263445;
}

.fm-header-title p {
    margin: 0;
    color: #8a96a5;
    font-size: 12px;
}

.fm-header-search {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 350px;
    max-width: 45%;
    height: 42px;
    padding: 0 13px;
    border: 1px solid #e0e6ed;
    border-radius: 7px;
    background: #ffffff;
}

.fm-header-search i {
    color: #98a4b2;
}

.fm-header-search input {
    width: 100%;
    min-width: 0;
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: transparent;
    font-size: 12px;
}

.fm-refresh-btn {
    width: 40px;
    height: 40px;
    border: 1px solid #e0e6ed;
    border-radius: 7px;
    background: #ffffff;
    color: #657386;
    cursor: pointer;
}

.fm-refresh-btn:hover {
    color: #3478df;
    background: #f0f5ff;
}

/* =========================================
   CONTENT AND SECTIONS
========================================= */

.fm-content {
    width: 100%;
}

.fm-section {
    margin-top: 30px;
}

.fm-section-header,
.fm-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    margin-bottom: 17px;
}

.fm-section-header h3,
.fm-toolbar h3 {
    margin: 0 0 6px;
    font-size: 17px;
    font-weight: 700;
    color: #263445;
}

.fm-section-header p,
.fm-toolbar p {
    margin: 0;
    font-size: 12px;
    color: #8a96a5;
}

.fm-toolbar-actions {
    display: flex;
    align-items: center;
    gap: 9px;
}

.fm-subsection {
    margin-top: 27px;
}

.fm-subsection h4 {
    font-size: 14px;
    font-weight: 700;
    margin: 0 0 15px;
    color: #344256;
}

/* =========================================
   WELCOME SECTION
========================================= */

.fm-welcome {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-height: 145px;
    padding: 25px 30px;
    border-radius: 11px;
    background: linear-gradient(110deg, #eaf2ff, #f4f7ff);
    border: 1px solid #e2ebfc;
}

.fm-welcome h3 {
    margin: 0 0 9px;
    color: #263e64;
    font-size: 22px;
    font-weight: 700;
}

.fm-welcome p {
    margin: 0;
    color: #7588a4;
    font-size: 13px;
}

.fm-welcome-icon {
    width: 75px;
    height: 75px;
    border-radius: 50%;
    background: #ffffff;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #3478df;
    font-size: 32px;
}

/* =========================================
   STATISTICS CARDS
========================================= */

.fm-stats {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 16px;
    margin-top: 22px;
}

.fm-stat-card {
    display: flex;
    align-items: center;
    gap: 15px;
    min-height: 95px;
    padding: 18px;
    border: 1px solid #e9edf2;
    border-radius: 9px;
    background: #ffffff;
}

.fm-stat-card span {
    display: block;
    color: #8793a3;
    font-size: 11px;
    margin-bottom: 7px;
}

.fm-stat-card strong {
    display: block;
    color: #263445;
    font-size: 22px;
}

.fm-stat-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 43px;
    height: 43px;
    border-radius: 9px;
    font-size: 17px;
}

.fm-stat-icon.blue {
    background: #eaf1ff;
    color: #3478df;
}

.fm-stat-icon.purple {
    background: #f1eaff;
    color: #8856cf;
}

.fm-stat-icon.green {
    background: #e8f8ef;
    color: #28a365;
}

/* =========================================
   BUTTONS
========================================= */

.fm-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;
    min-height: 36px;
    padding: 8px 13px;
    border: 1px solid #dfe5ed;
    border-radius: 6px;
    background: #ffffff;
    color: #536174;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    text-decoration: none;
}

.fm-button:hover {
    background: #f5f8fc;
    color: #3478df;
    border-color: #b8cff4;
}

.fm-button.fm-primary {
    color: #ffffff;
    background: #3478df;
    border-color: #3478df;
}

.fm-button.fm-primary:hover {
    background: #2867c5;
    color: #ffffff;
}

.fm-button:disabled,
.fm-button[disabled],
.fm-disabled {
    opacity: 0.55;
    cursor: not-allowed;
}

.fm-back-btn {
    display: block;
    padding: 0;
    margin-bottom: 12px;
    border: none;
    background: transparent;
    color: #3478df;
    font-size: 12px;
    cursor: pointer;
}

.fm-back-btn i {
    margin-right: 6px;
}

/* =========================================
   FOLDER CARDS
========================================= */

.fm-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 14px;
}

.fm-folder-card {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    min-height: 82px;
    padding: 14px;
    border: 1px solid #e7ebf1;
    border-radius: 9px;
    background: #ffffff;
    transition: all 0.2s ease;
}

.fm-folder-card:hover {
    border-color: #b8cff4;
    box-shadow: 0 4px 13px rgba(37, 75, 125, 0.07);
}

.fm-folder-main {
    display: flex;
    align-items: center;
    gap: 12px;
    flex: 1;
    min-width: 0;
    cursor: pointer;
}

.fm-folder-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 43px;
    height: 43px;
    min-width: 43px;
    border-radius: 9px;
    background: #fff4dc;
    color: #e6a52c;
    font-size: 20px;
}

.fm-card-info {
    display: flex;
    flex-direction: column;
    min-width: 0;
    gap: 6px;
}

.fm-card-info strong {
    color: #344256;
    font-size: 12px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.fm-card-info span {
    color: #95a0ad;
    font-size: 10px;
}

.fm-card-arrow {
    color: #aab4c0;
    font-size: 17px;
}

.fm-card-menu {
    display: flex;
    gap: 5px;
}

.fm-card-menu button {
    width: 28px;
    height: 28px;
    border: none;
    border-radius: 5px;
    background: transparent;
    color: #7e8a99;
    cursor: pointer;
}

.fm-card-menu button:hover {
    background: #f0f5ff;
    color: #3478df;
}

/* =========================================
   FILE TABLE
========================================= */

.fm-table-wrap {
    width: 100%;
    overflow-x: auto;
    border: 1px solid #e8edf2;
    border-radius: 8px;
    background: #ffffff;
}

.fm-table {
    width: 100%;
    border-collapse: collapse;
    min-width: 570px;
}

.fm-table th {
    padding: 13px 16px;
    text-align: left;
    background: #f8fafd;
    border-bottom: 1px solid #e9edf2;
    color: #8793a3;
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.fm-table td {
    padding: 13px 16px;
    border-bottom: 1px solid #eef1f5;
    color: #667386;
    font-size: 12px;
}

.fm-table tbody tr:last-child td {
    border-bottom: none;
}

.fm-table tbody tr:hover {
    background: #fafcff;
}

.fm-file-name {
    display: flex;
    align-items: center;
    gap: 10px;
    color: #344256;
    font-weight: 600;
}

.fm-file-name i,
.fm-table-icon {
    color: #6889bd;
    font-size: 15px;
}

.fm-permission {
    display: inline-block;
    padding: 4px 8px;
    border-radius: 4px;
    background: #eef4ff;
    color: #3478df;
    font-size: 10px;
}

.fm-actions {
    display: flex;
    align-items: center;
    gap: 5px;
}

.fm-actions button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 29px;
    height: 29px;
    border: none;
    border-radius: 5px;
    background: transparent;
    color: #718096;
    cursor: pointer;
}

.fm-actions button:hover {
    background: #edf3ff;
    color: #3478df;
}

/* =========================================
   EMPTY STATES
========================================= */

.fm-empty {
    padding: 35px 15px;
    text-align: center;
    color: #98a4b2;
}

.fm-empty > i {
    display: block;
    margin-bottom: 12px;
    font-size: 32px;
    color: #c4cfdb;
}

.fm-empty p {
    margin: 0 0 12px;
    font-size: 12px;
}

/* =========================================
   ALERT MESSAGES
========================================= */

.fm-alert {
    display: flex;
    align-items: center;
    gap: 9px;
    padding: 11px 13px;
    margin-bottom: 15px;
    border-radius: 6px;
    font-size: 12px;
}

.fm-alert button {
    margin-left: auto;
    border: none;
    background: transparent;
    font-size: 19px;
    cursor: pointer;
}

.fm-alert-success {
    background: #eaf8ef;
    color: #25844d;
    border: 1px solid #d5efdf;
}

.fm-alert-error {
    background: #fff0f0;
    color: #c24c4c;
    border: 1px solid #f4dada;
}

/* =========================================
   MODAL
========================================= */

.fm-modal-backdrop {
    position: fixed;
    inset: 0;
    z-index: 9999;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 18px;
    background: rgba(25, 38, 55, 0.48);
}

.fm-modal {
    width: 100%;
    max-width: 440px;
    max-height: 90vh;
    overflow-y: auto;
    padding: 24px;
    border-radius: 11px;
    background: #ffffff;
    box-shadow: 0 15px 50px rgba(0, 0, 0, 0.16);
}

.fm-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 22px;
}

.fm-modal-header h3 {
    margin: 0;
    color: #263445;
    font-size: 18px;
    font-weight: 700;
}

.fm-modal-header button {
    width: 30px;
    height: 30px;
    border: none;
    border-radius: 5px;
    background: #f1f4f8;
    color: #68778a;
    font-size: 21px;
    cursor: pointer;
}

.fm-modal label {
    display: block;
    margin: 14px 0 7px;
    color: #526174;
    font-size: 12px;
    font-weight: 600;
}

.fm-modal input[type="text"],
.fm-modal select,
.fm-modal textarea {
    width: 100%;
    min-height: 40px;
    padding: 9px 11px;
    border: 1px solid #dce3eb;
    border-radius: 6px;
    outline: none;
    background: #ffffff;
    color: #344256;
    font-size: 12px;
    box-shadow: none;
}

.fm-modal input:focus,
.fm-modal select:focus,
.fm-modal textarea:focus {
    border-color: #78a5e8;
    box-shadow: 0 0 0 2px rgba(52, 120, 223, 0.08);
}

.fm-modal textarea {
    resize: vertical;
}

.fm-modal-actions {
    display: flex;
    justify-content: flex-end;
    gap: 9px;
    margin-top: 23px;
}

/* =========================================
   SHARE USER SEARCH
========================================= */

.fm-share-modal {
    max-width: 480px;
}

.fm-user-search {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
    min-height: 42px;
    padding: 0 12px;
    margin-top: 6px;
    border: 1px solid #d7dfe8;
    border-radius: 6px;
    background: #ffffff;
}

.fm-user-search i {
    color: #8291a2;
    font-size: 13px;
}

.fm-user-search input {
    flex: 1;
    width: 100%;
    min-width: 0;
    height: 38px;
    padding: 0;
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: transparent;
    font-size: 12px;
}

.fm-user-search input:focus {
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
}

.fm-search-help {
    margin: 6px 0 14px;
    color: #8995a2;
    font-size: 11px;
}

.fm-user-status {
    padding: 10px 0;
    color: #718096;
    font-size: 12px;
}

.fm-user-status i {
    margin-right: 6px;
}

.fm-user-error {
    color: #c24c4c;
}

/* =========================================
   IMAGE PREVIEW
========================================= */

.fm-preview-backdrop {
    z-index: 10000;
}

.fm-preview-modal {
    display: flex;
    flex-direction: column;
    width: 100%;
    max-width: 850px;
    max-height: 90vh;
    overflow: hidden;
    border-radius: 10px;
    background: #ffffff;
}

.fm-preview-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    padding: 15px 20px;
    border-bottom: 1px solid #e9edf2;
    color: #344256;
    font-size: 13px;
}

.fm-preview-header button {
    width: 30px;
    height: 30px;
    border: none;
    border-radius: 5px;
    background: #f1f4f8;
    color: #68778a;
    font-size: 21px;
    cursor: pointer;
}

.fm-preview-content {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 250px;
    max-height: 65vh;
    padding: 20px;
    overflow: auto;
    background: #f7f9fc;
}

.fm-preview-content img {
    display: block;
    max-width: 100%;
    max-height: 60vh;
    object-fit: contain;
}

.fm-preview-footer {
    display: flex;
    justify-content: flex-end;
    gap: 10px;
    padding: 13px 20px;
    border-top: 1px solid #e9edf2;
}

/* =========================================
   STORAGE
========================================= */

.fm-storage-card {
    display: flex;
    align-items: center;
    gap: 18px;
    padding: 23px;
    border: 1px solid #e6ecf3;
    border-radius: 9px;
    background: #ffffff;
}

.fm-storage-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 55px;
    height: 55px;
    border-radius: 10px;
    background: #eaf1ff;
    color: #3478df;
    font-size: 23px;
}

.fm-storage-card h3 {
    margin: 0 0 7px;
    font-size: 16px;
    color: #344256;
}

.fm-storage-card p {
    margin: 0;
    color: #8a96a5;
    font-size: 12px;
}

.fm-storage-note {
    margin-top: 17px;
    color: #8a96a5;
    font-size: 11px;
    line-height: 1.6;
}

.fm-restore {
    color: #268a57;
    border-color: #ccebd8;
    background: #effaf3;
}

.fm-restore:hover {
    color: #197344;
    background: #e2f6e9;
}

/* =========================================
   RESPONSIVE DESIGN
========================================= */

@media (max-width: 900px) {
    .fm-sidebar {
        width: 190px;
        min-width: 190px;
    }

    .fm-main {
        padding: 20px;
    }

    .fm-stats {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .fm-header-search {
        max-width: 40%;
    }
}

@media (max-width: 650px) {
    .fm-app {
        display: block;
    }

    .fm-sidebar {
        width: 100%;
        min-width: 0;
        min-height: auto;
    }

    .fm-logo {
        height: 60px;
    }

    .fm-menu {
        display: flex;
        flex-wrap: wrap;
        gap: 5px;
        padding: 10px;
    }

    .fm-menu-label {
        display: none;
    }

    .fm-menu a {
        flex: 1 1 42%;
        margin: 0;
    }

    .fm-sidebar-footer {
        display: none;
    }

    .fm-main {
        padding: 16px;
    }

    .fm-header {
        flex-wrap: wrap;
    }

    .fm-header-search {
        order: 3;
        width: 100%;
        max-width: 100%;
    }

    .fm-stats {
        grid-template-columns: 1fr;
    }

    .fm-toolbar {
        align-items: flex-start;
        flex-direction: column;
    }

    .fm-toolbar-actions {
        width: 100%;
        flex-wrap: wrap;
    }

    .fm-grid {
        grid-template-columns: 1fr;
    }

    .fm-welcome {
        padding: 20px;
    }

    .fm-welcome h3 {
        font-size: 18px;
    }

    .fm-welcome-icon {
        width: 52px;
        height: 52px;
        font-size: 23px;
    }
}

sp_widget.script:
(function () {
    var FILE_TABLE = 'x_1830514_fm_file';
    var FOLDER_TABLE = 'x_1830514_fm_folder';
    var SHARE_TABLE = 'x_1830514_fm_share';
    var FOLDER_TABLE_NAME = 'x_1830514_fm_folder';

    var userId = gs.getUserID();

    data.files = [];
    data.folders = [];
    data.sharedFiles = [];
    data.sharedFolders = [];
    data.recycleFiles = [];
    data.recycleFolders = [];
    data.users = [];
    data.storage = {
        fileCount: 0,
        totalBytes: 0
    };
    data.error = '';
    data.success = '';

    // Search users returns only search results.
    if (input && input.action == 'search_users') {
        searchUsers();
        return;
    }

    if (input && input.action) {
        processAction();

        // Do not reload all widget data after an unsuccessful action.
        if (data.error)
            return;
    }

    loadData();

    // --------------------------------------------------
    // ACTION HANDLER
    // --------------------------------------------------

    function processAction() {
        switch (input.action) {
            case 'create_folder':
                createFolder();
                break;

            case 'create_file':
                createFile();
                break;

            case 'update_file':
                updateFile();
                break;

            case 'delete_file':
                deleteFile();
                break;

            case 'delete_folder':
                deleteFolder();
                break;

            case 'restore_file':
                restoreFile();
                break;

            case 'restore_folder':
                restoreFolder();
                break;

            case 'share':
                shareItem();
                break;

            default:
                data.error = 'Invalid action.';
        }
    }

    // --------------------------------------------------
    // COMMON HELPERS
    // --------------------------------------------------

    function getRecord(table, sysId) {
        if (!sysId)
            return null;

        var gr = new GlideRecordSecure(table);

        if (!gr.get(sysId) || !gr.canRead())
            return null;

        return gr;
    }

    function isDeleted(gr) {
        return gr.getValue('is_deleted') == '1';
    }

    function isActiveShare(share) {
        if (share.getValue('active') != '1')
            return false;

        var expiry = share.getValue('expiration_date');

        if (expiry) {
            var expiryDate = new GlideDateTime(expiry);
            var now = new GlideDateTime();

            if (expiryDate.getNumericValue() < now.getNumericValue())
                return false;
        }

        return true;
    }

    function getDirectShare(tableField, sysId) {
        var share = new GlideRecordSecure(SHARE_TABLE);
        share.addQuery(tableField, sysId);
        share.addQuery('shared_with_user', userId);
        share.addQuery('active', true);
        share.query();

        while (share.next()) {
            if (isActiveShare(share))
                return share.getValue('permission') || 'Viewer';
        }

        return '';
    }

    function getFolderPermission(folderId) {
        if (!folderId)
            return '';

        var folder = getRecord(FOLDER_TABLE, folderId);

        if (!folder || isDeleted(folder))
            return '';

        if (folder.getValue('owner') == userId)
            return 'Owner';

        return getDirectShare('folder', folderId);
    }

    function getFilePermission(file) {
        if (!file || isDeleted(file))
            return '';

        if (file.getValue('owner') == userId)
            return 'Owner';

        var directPermission = getDirectShare(
            'file',
            file.getUniqueValue()
        );

        if (directPermission)
            return directPermission;

        var folderId = file.getValue('folder');

        if (folderId)
            return getFolderPermission(folderId);

        return '';
    }

    function canEditFile(file) {
        var permission = getFilePermission(file);
        return permission == 'Owner' || permission == 'Editor';
    }

    function canEditFolder(folder) {
        var permission = getFolderPermission(
            folder.getUniqueValue()
        );

        return permission == 'Owner' || permission == 'Editor';
    }

    function canOwnFile(file) {
        return file && file.getValue('owner') == userId;
    }

    function canOwnFolder(folder) {
        return folder && folder.getValue('owner') == userId;
    }

    function getAttachmentId(fileId) {
        var attachment = new GlideRecordSecure('sys_attachment');
        attachment.addQuery('table_name', FILE_TABLE);
        attachment.addQuery('table_sys_id', fileId);
        attachment.orderByDesc('sys_created_on');
        attachment.setLimit(1);
        attachment.query();

        if (attachment.next() && attachment.canRead())
            return attachment.getUniqueValue();

        return '';
    }

    function addFileToList(file, target) {
        var permission = getFilePermission(file);

        if (!permission)
            return;

        target.push({
            sys_id: file.getUniqueValue(),
            filename: file.getValue('filename') || '',
            folder: file.getValue('folder') || '',
            description: file.getValue('description') || '',
            owner: file.getValue('owner') || '',
            file_extension: file.getValue('file_extension') || '',
            file_size: parseInt(file.getValue('file_size'), 10) || 0,
            content_type: file.getValue('content_type') || '',
            attachment_id: getAttachmentId(file.getUniqueValue()),
            permission: permission,
            can_edit: permission == 'Owner' || permission == 'Editor'
        });
    }

    function addFolderToList(folder, target) {
        var permission = getFolderPermission(
            folder.getUniqueValue()
        );

        if (!permission)
            return;

        target.push({
            sys_id: folder.getUniqueValue(),
            folder_name: folder.getValue('folder_name') || '',
            parent_folder: folder.getValue('parent_folder') || '',
            description: folder.getValue('description') || '',
            owner: folder.getValue('owner') || '',
            permission: permission,
            can_edit: permission == 'Owner' || permission == 'Editor'
        });
    }

    // --------------------------------------------------
    // SEARCH USERS
    // --------------------------------------------------

    function searchUsers() {
        data.users = [];

        var searchText = (input.search_term || '').trim();

        if (searchText.length < 2) {
            return;
        }

        var users = new GlideRecordSecure('sys_user');

        users.addQuery('active', true);
        users.addQuery('sys_id', '!=', userId);

        var condition = users.addQuery(
            'name',
            'CONTAINS',
            searchText
        );

        condition.addOrCondition(
            'user_name',
            'CONTAINS',
            searchText
        );

        condition.addOrCondition(
            'email',
            'CONTAINS',
            searchText
        );

        users.orderBy('name');
        users.setLimit(50);
        users.query();

        while (users.next()) {
            if (!users.canRead())
                continue;

            data.users.push({
                sys_id: users.getUniqueValue(),
                name: users.getValue('name') || '',
                user_name: users.getValue('user_name') || '',
                email: users.getValue('email') || ''
            });
        }
    }

    // --------------------------------------------------
    // CREATE FOLDER WITH DUPLICATE CHECK
    // --------------------------------------------------

    function createFolder() {
        var folderName = (input.folder_name || '').trim();
        var parentFolder = input.parent_folder || '';

        if (!folderName) {
            data.error = 'Please enter a folder name.';
            return;
        }

        if (folderName.length > 40) {
            data.error = 'Folder name cannot exceed 40 characters.';
            return;
        }

        if (parentFolder) {
            var parent = getRecord(FOLDER_TABLE, parentFolder);

            if (!parent || isDeleted(parent) ||
                !canEditFolder(parent)) {
                data.error = 'You do not have permission to create a subfolder here.';
                return;
            }
        }

        var duplicate = new GlideRecordSecure(FOLDER_TABLE);
        duplicate.addQuery('owner', userId);
        duplicate.addQuery('folder_name', folderName);
        duplicate.addQuery('is_deleted', false);

        if (parentFolder)
            duplicate.addQuery('parent_folder', parentFolder);
        else
            duplicate.addNullQuery('parent_folder');

        duplicate.setLimit(1);
        duplicate.query();

        if (duplicate.next()) {
            data.error =
                'This folder name already exists in this location.';
            return;
        }

        var folder = new GlideRecordSecure(FOLDER_TABLE);
        folder.initialize();
        folder.setValue('folder_name', folderName);
        folder.setValue('owner', userId);
        folder.setValue('description', input.description || '');
        folder.setValue('is_deleted', false);
        folder.setValue('active', true);

        if (parentFolder)
            folder.setValue('parent_folder', parentFolder);

        var folderId = folder.insert();

        if (!folderId) {
            data.error = 'Unable to create folder.';
            return;
        }

        data.success = 'Folder created successfully.';
        data.folder_sys_id = folderId;
    }

    // --------------------------------------------------
    // CREATE FILE RECORD
    // --------------------------------------------------

    function createFile() {
        var filename = (input.filename || '').trim();
        var folderId = input.folder || '';

        if (!filename || !folderId) {
            data.error = 'File name and destination folder are required.';
            return;
        }

        var folder = getRecord(FOLDER_TABLE, folderId);

        if (!folder || isDeleted(folder) || !canEditFolder(folder)) {
            data.error = 'You do not have permission to upload into this folder.';
            return;
        }

        var file = new GlideRecordSecure(FILE_TABLE);
        file.initialize();
        file.setValue('filename', filename);
        file.setValue('folder', folderId);
        file.setValue('owner', userId);
        file.setValue('file_extension', input.extension || '');
        file.setValue('file_size', parseInt(input.file_size, 10) || 0);
        file.setValue('content_type', input.content_type || '');
        file.setValue('is_deleted', false);
        file.setValue('current_version', 1);

        var fileId = file.insert();

        if (!fileId) {
            data.error = 'Unable to create file record.';
            return;
        }

        data.file_sys_id = fileId;
        data.success = 'File record created.';
    }

    // --------------------------------------------------
    // UPDATE FILE
    // --------------------------------------------------

    function updateFile() {
        var file = getRecord(FILE_TABLE, input.sys_id);

        if (!file || isDeleted(file)) {
            data.error = 'File not found.';
            return;
        }

        if (!canEditFile(file)) {
            data.error = 'You do not have permission to edit this file.';
            return;
        }

        file.setValue('description', input.description || '');

        if (!file.update()) {
            data.error = 'Unable to update file.';
            return;
        }

        data.success = 'File updated successfully.';
    }

    // --------------------------------------------------
    // DELETE FILE
    // --------------------------------------------------

    function deleteFile() {
        var file = getRecord(FILE_TABLE, input.sys_id);

        if (!file || isDeleted(file) || !canOwnFile(file)) {
            data.error = 'Only the file owner can delete this file.';
            return;
        }

        file.setValue('original_folder', file.getValue('folder'));
        file.setValue('is_deleted', true);
        file.setValue('deleted_by', userId);
        file.setValue('deleted_date', new GlideDateTime());
        file.update();

        data.success = 'File moved to Recycle Bin.';
    }

    // --------------------------------------------------
    // DELETE EMPTY FOLDER
    // --------------------------------------------------

    function deleteFolder() {
        var folder = getRecord(FOLDER_TABLE, input.sys_id);

        if (!folder || isDeleted(folder) || !canOwnFolder(folder)) {
            data.error = 'Only the folder owner can delete this folder.';
            return;
        }

        var childFolders = new GlideRecordSecure(FOLDER_TABLE);
        childFolders.addQuery('parent_folder', folder.getUniqueValue());
        childFolders.addQuery('is_deleted', false);
        childFolders.setLimit(1);
        childFolders.query();

        if (childFolders.hasNext()) {
            data.error = 'Delete or move the subfolders first.';
            return;
        }

        var files = new GlideRecordSecure(FILE_TABLE);
        files.addQuery('folder', folder.getUniqueValue());
        files.addQuery('is_deleted', false);
        files.setLimit(1);
        files.query();

        if (files.hasNext()) {
            data.error = 'Delete or move the files in this folder first.';
            return;
        }

        folder.setValue('is_deleted', true);
        folder.setValue('deleted_by', userId);
        folder.setValue('deleted_date', new GlideDateTime());
        folder.setValue('active', false);
        folder.update();

        data.success = 'Folder moved to Recycle Bin.';
    }

    // --------------------------------------------------
    // RESTORE FILE
    // --------------------------------------------------

    function restoreFile() {
        var file = getRecord(FILE_TABLE, input.sys_id);

        if (!file || !canOwnFile(file) || !isDeleted(file)) {
            data.error = 'You cannot restore this file.';
            return;
        }

        var originalFolder = file.getValue('original_folder');

        if (originalFolder) {
            var folder = getRecord(FOLDER_TABLE, originalFolder);

            if (!folder || isDeleted(folder)) {
                data.error = 'Restore the original folder first.';
                return;
            }

            file.setValue('folder', originalFolder);
        }

        file.setValue('is_deleted', false);
        file.setValue('deleted_by', '');
        file.setValue('deleted_date', '');
        file.update();

        data.success = 'File restored successfully.';
    }

    // --------------------------------------------------
    // RESTORE FOLDER
    // --------------------------------------------------

    function restoreFolder() {
        var folder = getRecord(FOLDER_TABLE, input.sys_id);

        if (!folder || !canOwnFolder(folder) || !isDeleted(folder)) {
            data.error = 'You cannot restore this folder.';
            return;
        }

        var parentId = folder.getValue('parent_folder');

        if (parentId) {
            var parent = getRecord(FOLDER_TABLE, parentId);

            if (!parent || isDeleted(parent)) {
                data.error = 'Restore the parent folder first.';
                return;
            }
        }

        var duplicate = new GlideRecordSecure(FOLDER_TABLE);
        duplicate.addQuery('owner', userId);
        duplicate.addQuery('folder_name', folder.getValue('folder_name'));
        duplicate.addQuery('is_deleted', false);
        duplicate.addQuery('sys_id', '!=', folder.getUniqueValue());

        if (parentId)
            duplicate.addQuery('parent_folder', parentId);
        else
            duplicate.addNullQuery('parent_folder');

        duplicate.setLimit(1);
        duplicate.query();

        if (duplicate.next()) {
            data.error = 'A folder with this name already exists.';
            return;
        }

        folder.setValue('is_deleted', false);
        folder.setValue('deleted_by', '');
        folder.setValue('deleted_date', '');
        folder.setValue('active', true);
        folder.update();

        data.success = 'Folder restored successfully.';
    }

    // --------------------------------------------------
    // SHARE FILE OR FOLDER
    // --------------------------------------------------

    function shareItem() {
        var type = input.type;
        var itemId = input.sys_id;
        var targetUser = input.user_id;
        var permission = input.permission;

        if (!targetUser || !itemId) {
            data.error = 'Select a user and item.';
            return;
        }

        if (permission != 'Viewer' && permission != 'Editor') {
            data.error = 'Invalid permission.';
            return;
        }

        if (targetUser == userId) {
            data.error = 'You cannot share with yourself.';
            return;
        }

        // Confirm recipient is an active readable user.
        var user = new GlideRecordSecure('sys_user');

        if (!user.get(targetUser) ||
            user.getValue('active') != '1' ||
            !user.canRead()) {
            data.error = 'Selected user is not available.';
            return;
        }

        var targetField;
        var item;

        if (type == 'file') {
            item = getRecord(FILE_TABLE, itemId);
            targetField = 'file';

            if (!item || isDeleted(item) || !canOwnFile(item)) {
                data.error = 'Only the file owner can share this file.';
                return;
            }

        } else if (type == 'folder') {
            item = getRecord(FOLDER_TABLE, itemId);
            targetField = 'folder';

            if (!item || isDeleted(item) || !canOwnFolder(item)) {
                data.error = 'Only the folder owner can share this folder.';
                return;
            }

        } else {
            data.error = 'Invalid item type.';
            return;
        }

        var existing = new GlideRecordSecure(SHARE_TABLE);
        existing.addQuery(targetField, itemId);
        existing.addQuery('shared_with_user', targetUser);
        existing.query();

        if (existing.next()) {
            existing.setValue('active', true);
            existing.setValue('permission', permission);
            existing.setValue('shared_by', userId);
            existing.update();

        } else {
            var share = new GlideRecordSecure(SHARE_TABLE);
            share.initialize();
            share.setValue(targetField, itemId);
            share.setValue('shared_with_user', targetUser);
            share.setValue('shared_by', userId);
            share.setValue('permission', permission);
            share.setValue('active', true);

            if (!share.insert()) {
                data.error = 'Unable to share this item.';
                return;
            }
        }

        data.success = 'Item shared successfully.';
    }

    // --------------------------------------------------
    // LOAD WIDGET DATA
    // --------------------------------------------------

    function loadData() {
        loadOwnedFolders();
        loadOwnedFiles();
        loadSharedItems();
        loadRecycleBin();
        loadStorage();
    }

    function loadOwnedFolders() {
        var folders = new GlideRecordSecure(FOLDER_TABLE);
        folders.addQuery('owner', userId);
        folders.addQuery('is_deleted', false);
        folders.orderBy('folder_name');
        folders.query();

        while (folders.next())
            addFolderToList(folders, data.folders);
    }

    function loadOwnedFiles() {
        var files = new GlideRecordSecure(FILE_TABLE);
        files.addQuery('owner', userId);
        files.addQuery('is_deleted', false);
        files.orderByDesc('sys_created_on');
        files.query();

        while (files.next())
            addFileToList(files, data.files);
    }

    function loadSharedItems() {
        var shares = new GlideRecordSecure(SHARE_TABLE);
        shares.addQuery('shared_with_user', userId);
        shares.addQuery('active', true);
        shares.query();

        while (shares.next()) {
            if (!isActiveShare(shares))
                continue;

            var fileId = shares.getValue('file');
            var folderId = shares.getValue('folder');

            if (fileId) {
                var file = getRecord(FILE_TABLE, fileId);

                if (file && !isDeleted(file) && !canOwnFile(file))
                    addFileToList(file, data.sharedFiles);
            }

            if (folderId) {
                var folder = getRecord(FOLDER_TABLE, folderId);

                if (folder && !isDeleted(folder) && !canOwnFolder(folder))
                    addFolderToList(folder, data.sharedFolders);
            }
        }
    }

    function loadRecycleBin() {
        var files = new GlideRecordSecure(FILE_TABLE);
        files.addQuery('owner', userId);
        files.addQuery('is_deleted', true);
        files.orderByDesc('deleted_date');
        files.query();

        while (files.next()) {
            data.recycleFiles.push({
                sys_id: files.getUniqueValue(),
                filename: files.getValue('filename') || '',
                file_size: parseInt(files.getValue('file_size'), 10) || 0
            });
        }

        var folders = new GlideRecordSecure(FOLDER_TABLE);
        folders.addQuery('owner', userId);
        folders.addQuery('is_deleted', true);
        folders.orderByDesc('deleted_date');
        folders.query();

        while (folders.next()) {
            data.recycleFolders.push({
                sys_id: folders.getUniqueValue(),
                folder_name: folders.getValue('folder_name') || ''
            });
        }
    }

    function loadStorage() {
        var files = new GlideRecordSecure(FILE_TABLE);
        files.addQuery('owner', userId);
        files.addQuery('is_deleted', false);
        files.query();

        while (files.next()) {
            data.storage.fileCount++;
            data.storage.totalBytes +=
                parseInt(files.getValue('file_size'), 10) || 0;
        }
    }

})();
